export const PASS_THRESHOLD = 70;

export function getAdaptiveExplanation(q, grade) {
  if (!q) return '';
  if (grade <= 3 && q.explanationSimple) return q.explanationSimple;
  if (grade >= 8 && q.explanationAdvanced) return q.explanationAdvanced;
  return q.explanation || '';
}

